WITH flattened_attrs AS (SELECT id, service, host, log_ts, level, status_code, context['region'] AS region, COALESCE(context['version'], 'none') AS version_or_default FROM app_logs) SELECT CASE WHEN status_code >= 407 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, COUNT(*) FILTER (WHERE service = 'auth') AS auth_rows, MAX(log_ts) AS ended_at FROM flattened_attrs GROUP BY CASE WHEN status_code >= 407 THEN 'HIGH' ELSE 'LOW' END HAVING COUNT(*) FILTER (WHERE service = 'auth') < 1000 ORDER BY auth_rows DESC NULLS LAST;
